package dispatch

import "time"

// Schedule knows when a carrier's departures are.
type Schedule struct {
	departures []time.Time
}

// NewSchedule returns a Schedule of the given departure times, in order.
func NewSchedule(departures ...time.Time) *Schedule {
	return &Schedule{departures: departures}
}

// NextDepartureAfter returns the first departure after t, and false if none.
func (s *Schedule) NextDepartureAfter(t time.Time) (time.Time, bool) {
	for _, departure := range s.departures {
		if departure.After(t) {
			return departure, true
		}
	}
	return time.Time{}, false
}

// Carrier moves shipments on a Schedule with a fixed transit time.
type Carrier struct {
	schedule *Schedule
	transit  time.Duration
}

// NewCarrier returns a Carrier with the given schedule and transit time.
func NewCarrier(schedule *Schedule, transit time.Duration) *Carrier {
	return &Carrier{schedule: schedule, transit: transit}
}

// Schedule returns the carrier's departure schedule.
func (c *Carrier) Schedule() *Schedule {
	return c.schedule
}

// Transit returns how long a shipment spends in transit.
func (c *Carrier) Transit() time.Duration {
	return c.transit
}
